{
  "design": {
    "theme": "studio",
    "picture_style": "photo"
  },
  "flow": [
    {"slide":1,"does":"Recall volume and time units","look_at":{"kind":"picture","shows":"Gas collected in a graduated syringe"},"teaches":[]},
    {"slide":2,"does":"Introduce the approved objectives","look_at":{"kind":"none","shows":null},"teaches":[]},
    {"slide":3,"does":"Teach gas collection and timed measurements","look_at":{"kind":"diagram","shows":"Magnesium and acid connected to a gas syringe"},"teaches":[2]},
    {"slide":4,"does":"Model a mean-rate calculation","look_at":{"kind":"none","shows":null},"teaches":[1]},
    {"slide":5,"does":"Check a matching mean-rate calculation","look_at":{"kind":"none","shows":null},"teaches":[1]},
    {"slide":6,"does":"Teach a controlled concentration investigation","look_at":{"kind":"diagram","shows":"Concentration changes while magnesium mass and temperature stay constant"},"teaches":[2]},
    {"slide":7,"does":"Check investigation design","look_at":{"kind":"none","shows":null},"teaches":[2]},
    {"slide":8,"does":"Teach concentration through collision theory","look_at":{"kind":"diagram","shows":"More acid particles in the same volume beside magnesium"},"teaches":[3]},
    {"slide":9,"does":"Correct the faster-particles misconception","look_at":{"kind":"diagram","shows":"Different particle numbers but equal typical speeds at the same temperature"},"teaches":[3]},
    {"slide":10,"does":"Check the collision explanation with a hinge","look_at":{"kind":"none","shows":null},"teaches":[3]},
    {"slide":11,"does":"Apply calculations to experimental evidence","look_at":{"kind":"none","shows":null},"teaches":[1,3]},
    {"slide":12,"does":"Evaluate an unfamiliar comparison and complete the worksheet exit ticket","look_at":{"kind":"none","shows":null},"teaches":[2,3]}
  ],
  "title": {
    "template": "title",
    "heading": "Rates of reaction",
    "lead": "Recall: which units measure gas volume and time?",
    "picture": {
      "shows": "a laboratory gas syringe with a visible graduated scale",
      "must_see": ["graduated syringe barrel","movable syringe plunger"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Measure gas as the reaction happens",
      "lead": "Magnesium + hydrochloric acid → magnesium chloride + hydrogen",
      "points": [
        "Collect hydrogen in a gas syringe.",
        "Start the timer when acid meets magnesium.",
        "Record gas volume every 10 seconds."
      ],
      "figure": {
        "kind": "labelled-diagram",
        "shows": "An airtight conical flask containing hydrochloric acid and magnesium ribbon, connected through a bung and delivery tube to a horizontally clamped gas syringe. Hydrogen moves the plunger outwards; the syringe plunger is free to move.",
        "labels": ["Gas syringe","Delivery tube","Bung","Hydrochloric acid","Magnesium ribbon","Stopwatch"]
      }
    },
    {
      "template": "equation-hero",
      "heading": "Worked example: mean rate",
      "lead": "Gas volume rises from 0 to 48 cm³ in 20 s.",
      "formula": "Mean rate = gas volume ÷ time",
      "points": [
        "Mean rate = 48 ÷ 20",
        "Mean rate = 2.4 cm³/s",
        "This is the average over the measured interval."
      ],
      "figure": null
    },
    {
      "template": "practice",
      "heading": "Calculate the mean rate",
      "questions": [
        "Gas volume rises from 0 to 54 cm³ in 20 s. Calculate the mean rate.",
        "Write the unit of your answer.",
        "Explain what your answer tells you about gas produced per second."
      ],
      "instruction": "Write the formula, substitution and answer.",
      "picture": null
    },
    {
      "template": "steps",
      "heading": "Change concentration fairly",
      "points": [
        "Use 25 cm³ acid; vary only its concentration.",
        "Keep magnesium mass and temperature the same.",
        "Record gas volume every 10 s for 60 s.",
        "Repeat each concentration three times; calculate means."
      ],
      "figure": {
        "kind": "table",
        "shows": "Three planned trials with different acid concentrations and the same magnesium mass and starting temperature. Hydrochloric acid is in excess at every concentration.",
        "alt": "Acid concentration varies between three trials; magnesium mass is 0.04 g and temperature is 20 degrees Celsius in each.",
        "title": null,
        "header": ["Acid (mol/dm³)","Mg (g)","Temp (°C)"],
        "rows": [["0.5","0.04","20"],["1.0","0.04","20"],["1.5","0.04","20"]]
      }
    },
    {
      "template": "question-set",
      "heading": "Plan the investigation",
      "questions": [
        "Compare 0.5 and 1.0 mol/dm³ hydrochloric acid. What will you change and measure?",
        "How will you control magnesium mass and temperature?",
        "How will you collect gas, time readings and make results more reliable?"
      ],
      "instruction": "Write a short method using a gas syringe.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Why does concentration matter?",
      "lead": "Higher concentration means more acid particles in each cm³.",
      "points": [
        "Acid particles hit the magnesium more often.",
        "A successful collision has enough energy to react.",
        "More successful collisions per second increase the rate."
      ],
      "figure": {
        "kind": "particles",
        "shows": "Two equal-volume panels with identical magnesium surfaces at 20 °C. The higher-concentration panel contains twice as many acid particles. Both panels show equal-length representative movement arrows and more contacts with magnesium in the higher-concentration panel.",
        "labels": ["Lower concentration","Higher concentration","Magnesium","Same temperature"]
      }
    },
    {
      "template": "visual-text",
      "heading": "More concentrated does not mean faster particles",
      "lead": "Both acids are at 20 °C. Their particles have the same average kinetic energy.",
      "points": [
        {"label":"What changes","text":"More particles occupy the same volume."},
        {"label":"Why rate rises","text":"More successful collisions occur each second."}
      ],
      "figure": {
        "kind": "particles",
        "shows": "Two equal-volume acid panels beside identical magnesium surfaces. One has fewer particles and one has more. Representative motion arrows have the same length in both panels, showing that concentration alone does not increase average particle speed.",
        "labels": ["0.5 mol/dm³","1.0 mol/dm³","Both at 20 °C"]
      }
    },
    {
      "template": "hinge",
      "heading": "Choose the best explanation",
      "stem": "At the same temperature, why does more concentrated acid react faster with magnesium?",
      "options": [
        "Acid particles move faster.",
        "More successful collisions occur each second.",
        "Every collision now causes a reaction.",
        "Each acid particle has more energy."
      ],
      "correct": 2
    },
    {
      "template": "practice",
      "heading": "Use the evidence",
      "questions": [
        "In 20 s, acid A produces 24 cm³ gas and acid B produces 40 cm³. Both start at 0 cm³. Calculate both mean rates.",
        "Both use 0.04 g magnesium, 25 cm³ acid and 20 °C. B is more concentrated. Explain its higher rate.",
        "Stretch: both acids are in excess. Predict whether the final gas volumes differ. Explain using the magnesium mass."
      ],
      "instruction": "Calculate, then explain using successful collisions.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Can this comparison be trusted?",
      "questions": [
        "Trial A uses 0.5 mol/dm³ acid at 20 °C; B uses 1.0 mol/dm³ at 30 °C. B is faster. Can concentration alone explain this?",
        "Both use 25 cm³ acid and 0.04 g magnesium. Describe a fair repeat using gas-volume readings.",
        "Predict the result of your fair repeat. Explain using successful collisions per second."
      ],
      "instruction": "Evaluate the claim and improve the investigation.",
      "picture": null
    }
  ]
}
